     7→  createBreadcrumbItem,
     8→  createLocationBreadcrumbItem,
     9→} from "./breadcrumb-stack";
    10→
    11→export interface BreadcrumbNodeDescriptor {
    12→  id?: string;
    13→  descriptorId?: string;
    14→  label: string;
    15→  icon?: IconData;
    16→  meta?: BreadcrumbStackItem["meta"];
    17→  sourceNodeId?: string;
    18→  parentNodeId?: string;
    19→  location?: DesktopLocation;
    20→}
    21→
    22→export interface ResolvedNavigationState<TValue> {
    23→  value: TValue;
    24→  breadcrumbStack: BreadcrumbStackItem[];
    25→}
    26→
    27→export function createBreadcrumbNode(
    28→  descriptor: BreadcrumbNodeDescriptor
    29→): BreadcrumbStackItem {
    30→  if (descriptor.location) {
    31→    return createLocationBreadcrumbItem(descriptor.location, {
    32→      ...descriptor,
    33→      descriptorId: descriptor.descriptorId,
    34→    });
    35→  }
    36→
    37→  return createBreadcrumbItem({
    38→    id: descriptor.id ?? descriptor.label,
    39→    label: descriptor.label,
    40→    icon: descriptor.icon,
    41→    meta: descriptor.meta,
    42→    sourceNodeId: descriptor.sourceNodeId,
    43→    parentNodeId: descriptor.parentNodeId,
    44→    descriptorId: descriptor.descriptorId,
    45→  });
    46→}
    47→
    48→export function buildBreadcrumbStack(
    49→  descriptors: BreadcrumbNodeDescriptor[]
    50→): BreadcrumbStackItem[] {
    51→  return descriptors.map(createBreadcrumbNode);
    52→}
    53→
    54→export function resolveNavigationState<TValue>(
    55→  value: TValue,
    56→  descriptors: BreadcrumbNodeDescriptor[]
    57→): ResolvedNavigationState<TValue> {
    58→  return {
    59→    value,
    60→    breadcrumbStack: buildBreadcrumbStack(descriptors),
    61→  };
    62→}
