   252→export function resolveSegmentDescriptorId(
   253→  segment: DesktopBreadcrumbSegment
   254→): string | undefined {
   255→  if (segment.descriptorId) {
   256→    return segment.descriptorId;
   257→  }
   258→
   259→  if (/^\/workspace\/[^/]+$/.test(segment.href)) {
   260→    return "workspace";
   261→  }
   262→
   263→  const sectionMatch = segment.href.match(
   264→    /^\/workspace\/[^/]+\/(chat|kanban|cron|ideas|files|github|chat-monitor)$/
   265→  );
   266→  if (sectionMatch) {
   267→    return `workspace-section:${sectionMatch[1]}`;
   268→  }
   269→
   270→  if (/^\/workspace\/[^/]+\/(agent|agents)$/.test(segment.href)) {
   271→    return "workspace-section:agent";
   272→  }
   273→
   274→  if (/^\/agent\/[^/]+/.test(segment.href)) {
   275→    return "workspace-agent";
   276→  }
   277→
   278→  if (/^\/executor\/[^/]+/.test(segment.href)) {
   279→    return "workspace-executor";
   280→  }
   281→
   282→  return undefined;
   283→}
